const INTERACTIONS_JS = `// Scroll reveal
        const observer = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                }
            });
        }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });

        document.querySelectorAll('.scroll-reveal').forEach(el => observer.observe(el));

        // Billing toggle
        let isAnnual = false;
        function toggleBilling() {
            isAnnual = !isAnnual;
            const dot = document.getElementById('toggleDot');
            const btn = document.getElementById('billingToggle');
            const monthlyLabel = document.getElementById('monthlyLabel');
            const annualLabel = document.getElementById('annualLabel');

            if (isAnnual) {
                dot.style.transform = 'translateX(24px)';
                btn.style.background = '#8b5cf6';
                dot.style.background = '#0f0720';
                monthlyLabel.style.color = '#71717A';
                annualLabel.style.color = '#FFFFFF';
            } else {
                dot.style.transform = 'translateX(0)';
                btn.style.background = 'rgba(255,255,255,0.1)';
                dot.style.background = '#FFFFFF';
                monthlyLabel.style.color = '#A3A3A3';
                annualLabel.style.color = '#A3A3A3';
            }

            document.querySelectorAll('.price-value').forEach(el => {
                const val = isAnnual ? el.dataset.annual : el.dataset.monthly;
                el.textContent = '$' + val;
            });
            document.querySelectorAll('.price-sub').forEach(el => {
                const val = isAnnual ? el.dataset.annual : el.dataset.monthly;
                el.textContent = val;
            });
        }

        // Smooth scroll for nav links
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                const target = document.querySelector(this.getAttribute('href'));
                if (target) {
                    e.preventDefault();
                    target.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }
            });
        });
    `;

